def _fit(part, x, dt, t):
    from scipy.optimize import least_squares
    y = _response(part).ravel()

    def matrix(tau):
        return _design(part, x, dt, t, tau).reshape(-1, 7)

    def residual(p):
        return matrix(p[:2]) @ p[2:] - y

    def jac(p):
        a = matrix(p[:2])
        cols = []
        for k in range(2):
            tm = p[:2].copy()
            tp = tm.copy()
            step = 1e-05 * tm[k]
            tm[k] -= step
            tp[k] += step
            cols.append((matrix(tp)[:, k] - matrix(tm)[:, k]) * (p[2 + k] / (2 * step)))
        return np.column_stack((*cols, a))
    bounds = (np.r_[[0.050001] * 2, [-np.inf] * 7], np.r_[[24.99999] * 2, [np.inf] * 7])
    best = None
    for tau in ([0.4, 2.5], [0.18, 6.0], [0.8, 12.0]):
        beta = np.linalg.lstsq(matrix(tau), y, rcond=None)[0]
        f = least_squares(residual, np.r_[tau, beta], jac=jac, bounds=bounds, loss='cauchy', f_scale=0.022, x_scale='jac', max_nfev=160)
        if best is None or f.cost < best.cost:
            best = f
    (tau, theta) = (best.x[:2].copy(), best.x[2:].copy())
    if tau[0] > tau[1]:
        tau = tau[::-1].copy()
        theta[:2] = theta[1::-1]
    return (tau, theta)

def _prepare(part, x, calibration):

    def total(raw):
        return (raw @ calibration[1:] + calibration[0]).sum(axis=-1)
    return (total(part['past_channel_raw']), total(part['hold_channel_raw']), np.column_stack((np.ones(len(x)), x)))
